package ai.eva.android.probe;
import android.app.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import android.webkit.*;
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.TimeUnit;

/** Dedicated file navigation and preview screen. */
public class FilesActivity extends ToolPageActivity {
    File currentFolder,previewFile,exportFile,importFolder;EditText search;LinearLayout rows;TextView count;ScrollView fileScroll;File[] entries=new File[0];java.util.Map<String,Integer> positions=new java.util.HashMap<>();
    File workspace(){File f=new File(getFilesDir(),"alpine/root/eva-workspace");f.mkdirs();try{return f.getCanonicalFile();}catch(IOException e){return f;}}
    public void onCreate(Bundle state){super.onCreate(state);page("文件","");String relative=getIntent().hasExtra("open-folder")?getIntent().getStringExtra("open-folder"):getSharedPreferences("eva-files",0).getString("folder","");File folder=new File(workspace(),relative);try{currentFolder=inWorkspace(folder)&&folder.isDirectory()?folder:workspace();}catch(Exception e){currentFolder=workspace();}files();if(state==null&&getIntent().hasExtra("open-file")){try{File selected=WorkspaceFiles.resolve(this,getIntent().getStringExtra("open-file"));if(selected.isFile()){currentFolder=selected.getParentFile();preview(selected);}}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}}if(state!=null&&state.containsKey("importFolder"))importFolder=new File(state.getString("importFolder"));if(state!=null&&state.containsKey("export"))exportFile=new File(state.getString("export"));if(state!=null&&state.containsKey("preview")){File file=new File(state.getString("preview"));if(file.isFile())preview(file);}}
    boolean inWorkspace(File f)throws IOException{String base=workspace().getCanonicalPath(),path=f.getCanonicalPath();return path.equals(base)||path.startsWith(base+File.separator);}
    void files(){previewFile=null;if(currentFolder==null)currentFolder=workspace();showFolder(currentFolder);}
    String size(long bytes){return bytes<1024?bytes+" B":bytes<1024*1024?String.format(java.util.Locale.ROOT,"%.1f KB",bytes/1024.0):String.format(java.util.Locale.ROOT,"%.1f MB",bytes/1048576.0);}
    void saveScroll(){if(currentFolder!=null&&previewFile==null&&fileScroll!=null)positions.put(currentFolder.getAbsolutePath(),fileScroll.getScrollY());}
    void showFolder(File folder){saveScroll();clear();pageTitle.setText("文件");while(header.getChildCount()>2)header.removeViewAt(2);header.addView(actionIcon("file","文件操作",()->folderActions()));header.addView(actionIcon("refresh","刷新目录",()->showFolder(currentFolder)));try{if(!inWorkspace(folder))throw new IOException("路径不在工作区内");currentFolder=folder;previewFile=null;
        LinearLayout breadcrumb=new LinearLayout(this);breadcrumb.setGravity(Gravity.CENTER_VERTICAL);View up=actionIcon("back","上一级目录",()->{if(!currentFolder.equals(workspace()))showFolder(currentFolder.getParentFile());});up.setEnabled(!folder.equals(workspace()));up.setAlpha(up.isEnabled()?1f:.25f);breadcrumb.addView(up);String relative=workspace().toPath().relativize(folder.toPath()).toString();TextView path=label(relative.isEmpty()?"工作区":"工作区 / "+relative.replace('\\','/'),12);path.setTextColor(0xff7a838e);path.setSingleLine();path.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);path.setOnClickListener(v->showFolder(workspace()));path.setContentDescription("返回工作区根目录");breadcrumb.addView(path,new LinearLayout.LayoutParams(0,dp(44),1));body.addView(breadcrumb);
        LinearLayout searchBar=new LinearLayout(this);searchBar.setGravity(Gravity.CENTER_VERTICAL);searchBar.setBackground(EvaUi.surface(this,paper==0xffFFFFFF?0xfff3f5f7:0xff282c32,10));View magnify=actionIcon("search","搜索当前文件夹",()->{search.requestFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,0);});searchBar.addView(magnify);search=new EditText(this);search.setSingleLine();search.setTextSize(13);search.setTextColor(ink);search.setHintTextColor(0xff858b92);search.setBackgroundColor(android.graphics.Color.TRANSPARENT);search.setPadding(0,0,dp(12),0);search.setHint("搜索当前文件夹");search.setContentDescription("搜索当前文件夹");searchBar.addView(search,new LinearLayout.LayoutParams(0,dp(42),1));body.addView(searchBar);
        count=label("",11);count.setTextColor(0xff858b92);LinearLayout.LayoutParams countLp=new LinearLayout.LayoutParams(-1,dp(38));body.addView(count,countLp);
        entries=folder.listFiles();if(entries==null)throw new IOException("无法读取这个目录");java.util.Arrays.sort(entries,(x,y)->x.isDirectory()!=y.isDirectory()?(x.isDirectory()?-1:1):x.getName().compareToIgnoreCase(y.getName()));
        fileScroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);fileScroll.addView(rows);body.addView(fileScroll,new LinearLayout.LayoutParams(-1,0,1));renderRows("");search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){renderRows(s.toString());}public void afterTextChanged(android.text.Editable e){}});Integer offset=positions.get(folder.getAbsolutePath());if(offset!=null)fileScroll.post(()->fileScroll.scrollTo(0,offset));
    }catch(Exception e){body.addView(label("无法打开："+e.getMessage(),14));TextView retry=label("返回工作区",14);retry.setTextColor(0xff3984ff);retry.setOnClickListener(v->showFolder(workspace()));body.addView(retry);}}
    void renderRows(String query){rows.removeAllViews();int found=0;for(File file:entries){if(!file.getName().toLowerCase(java.util.Locale.ROOT).contains(query.toLowerCase(java.util.Locale.ROOT)))continue;found++;
        LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));row.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x22888888),null,null));View glyph=actionIcon(file.isDirectory()?"folder":"file",file.isDirectory()?"文件夹":"文件",()->{});glyph.setClickable(false);glyph.setFocusable(false);((ImageView)glyph).setColorFilter(file.isDirectory()?0xff668ab2:0xff8d98a5);row.addView(glyph);
        LinearLayout words=new LinearLayout(this);words.setOrientation(1);words.setPadding(dp(8),0,dp(8),0);TextView name=label(file.getName(),14);name.setPadding(0,0,0,dp(5));name.setSingleLine();name.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);words.addView(name);String date=new java.text.SimpleDateFormat("MM-dd HH:mm",java.util.Locale.getDefault()).format(new java.util.Date(file.lastModified()));TextView metadata=label((file.isDirectory()?"文件夹":size(file.length()))+"  ·  "+date,11);metadata.setTextColor(0xff858b92);metadata.setPadding(0,0,0,0);words.addView(metadata);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));if(file.isDirectory()){TextView arrow=label("›",20);arrow.setTextColor(0xffadb4bc);row.addView(arrow);}
        row.setOnClickListener(v->{try{if(!inWorkspace(file))throw new IOException("链接指向工作区外，无法打开");if(file.isDirectory())showFolder(file);else preview(file);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});rows.addView(row,new LinearLayout.LayoutParams(-1,dp(68)));View line=new View(this);line.setBackgroundColor(paper==0xffFFFFFF?0xffeef1f4:0xff303236);rows.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
        count.setText(query.isEmpty()?found+" 个项目":"找到 "+found+" 个项目");if(found==0){TextView empty=label(query.isEmpty()?"文件夹是空的":"没有匹配的文件",14);empty.setGravity(Gravity.CENTER);empty.setTextColor(0xff858b92);empty.setPadding(0,dp(48),0,0);rows.addView(empty);}}
    void preview(File file){saveScroll();try{startActivity(new android.content.Intent(this,WorkspacePreviewActivity.class).putExtra("path",relative(file)));}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}}

    String relative(File file)throws IOException{return WorkspaceFiles.root(this).toPath().relativize(file.getAbsoluteFile().toPath().normalize()).toString().replace('\\','/');}
    void edit(File file){try{String path=relative(file);new WorkspaceEditor(WorkspaceFiles.root(this)).path(path);startActivity(new android.content.Intent(this,WorkspaceEditActivity.class).putExtra("path",path));}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}}
    void folderActions(){new AlertDialog.Builder(this).setTitle("工作区操作").setItems(new String[]{"新建文本文件","新建文件夹","从手机导入文件","未保存草稿","Git 版本管理","办公文档环境","从源码构建 APK"},(dialog,index)->{if(index<2){createEntry(index==1);return;}if(index==2){importFolder=currentFolder;startActivityForResult(new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT).addCategory(android.content.Intent.CATEGORY_OPENABLE).setType("*/*"),703);return;}if(index==3){showEditorDrafts();return;}try{startActivity(new android.content.Intent(this,index==4?GitActivity.class:index==5?OfficeActivity.class:AndroidBuildActivity.class).putExtra("folder",relative(currentFolder)));}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}}).show();}
    void showEditorDrafts(){java.util.ArrayList<String> paths=new java.util.ArrayList<>();File dir=new File(getFilesDir(),"editor-drafts");File[] drafts=dir.listFiles();if(drafts!=null)for(File f:drafts){if(!f.getName().endsWith(".json")||f.length()>2*1024*1024)continue;try{String path=new org.json.JSONObject(new String(Files.readAllBytes(f.toPath()),"UTF-8")).getString("path");new WorkspaceEditor(WorkspaceFiles.root(this)).path(path);paths.add(path);}catch(Exception ignored){}}if(paths.isEmpty()){Toast.makeText(this,"没有未保存草稿",0).show();return;}new AlertDialog.Builder(this).setTitle("恢复编辑草稿").setItems(paths.toArray(new String[0]),(d,n)->startActivity(new android.content.Intent(this,WorkspaceEditActivity.class).putExtra("path",paths.get(n)))).setNegativeButton("关闭",null).show();}
    void createEntry(boolean folder){EditText name=new EditText(this);name.setSingleLine();name.setHint(folder?"文件夹名称":"例如：笔记.md");AlertDialog dialog=new AlertDialog.Builder(this).setTitle(folder?"新建文件夹":"新建 UTF-8 文本文件").setView(name).setNegativeButton("取消",null).setPositiveButton("创建",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{String value=name.getText().toString().trim();if(value.isEmpty()||value.contains("/")||value.contains("\\"))throw new IOException("请输入名称，不包含目录");File dest=new File(currentFolder,value);new WorkspaceEditor(WorkspaceFiles.root(this)).create(relative(dest),"",folder);dialog.dismiss();showFolder(currentFolder);if(!folder)edit(dest);}catch(Exception e){name.setError(e.getMessage());}}));dialog.show();}
    void importDocument(android.net.Uri uri,File folder){Toast.makeText(this,"正在导入文件…",0).show();new Thread(()->{File temp=null;String message;try{
        String name="导入文件";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}if(name==null||name.trim().isEmpty())name="导入文件";name=name.replaceAll("[\\\\/\\p{Cntrl}:]","_");if(name.length()>100)name=name.substring(name.length()-100);if(name.equals(".")||name.equals(".."))name="导入文件";
        WorkspaceEditor store=new WorkspaceEditor(WorkspaceFiles.root(this));String prefix=relative(folder);String target=(prefix.isEmpty()?"":prefix+"/")+name;java.nio.file.Path destination=store.path(target);if(Files.exists(destination,LinkOption.NOFOLLOW_LINKS))throw new IOException("已有同名文件，请先重命名来源文件后重试");temp=File.createTempFile(".eva-import-",".tmp",folder);long size=0;
        try(InputStream input=getContentResolver().openInputStream(uri);OutputStream output=new FileOutputStream(temp)){if(input==null)throw new IOException("无法读取所选文件");byte[] buffer=new byte[32768];int n;while((n=input.read(buffer))!=-1){size+=n;if(size>64L*1024*1024)throw new IOException("文件超过 64 MB 导入上限");output.write(buffer,0,n);}}
        store.path(target);Files.move(temp.toPath(),destination);message="已导入："+name;
    }catch(Exception e){message="导入失败："+e.getMessage();}finally{if(temp!=null)temp.delete();}final String done=message;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;Toast.makeText(this,done,1).show();if(previewFile==null)showFolder(currentFolder);});},"eva-file-import").start();}
    protected void onResume(){super.onResume();if(currentFolder!=null){if(previewFile!=null)preview(previewFile);else showFolder(currentFolder);}}
    void leavePage(){onBackPressed();}
    protected void onPause(){saveScroll();if(currentFolder!=null)getSharedPreferences("eva-files",0).edit().putString("folder",workspace().toPath().relativize(currentFolder.toPath()).toString()).apply();super.onPause();}
    protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(importFolder!=null)out.putString("importFolder",importFolder.getAbsolutePath());if(exportFile!=null)out.putString("export",exportFile.getAbsolutePath());if(previewFile!=null)out.putString("preview",previewFile.getAbsolutePath());}
    public void onBackPressed(){if(previewFile!=null){showFolder(currentFolder);return;}if(currentFolder!=null&&!currentFolder.equals(workspace())){showFolder(currentFolder.getParentFile());return;}finish();}
}
